const BROWSER = 'mcp__claude-in-chrome__javascript_tool';

function resultWith( body: string, cost = 0.1 ): SDKMessage {
	return {
		type: 'result',
		subtype: 'success',
		uuid: `r-${ Math.random() }`,
		session_id: 'session-1',
		is_error: false,
		result: body,
		total_cost_usd: cost,
		duration_ms: 10,
	} as unknown as SDKMessage;
}

const report = ( status: string, summary: string ) =>
	'Summary.\n\n```json\n' + JSON.stringify( { release_console: { status, summary, files: [], followups: [ 'Merge the PR' ] } } ) + '\n```';

function start( script: Script, stageId = 'blog-draft' ) {
	const scripted = scriptedQuery( script );
	const manager = new RunManager( '/repo', scripted.queryFn );
	const run = manager.start( stageId, '4.17.5', `/x 4.17.5` );

	return { run, manager, scripted };
}

describe( 'browser scripts', () => {
	it( 'stops a write request from the browser for approval, without needing the version typed', async () => {
		let permission: PermissionResult | null = null;
		const script = "await wp.apiFetch( { path: '/wp/v2/posts', method: 'POST', data: { status: 'draft' } } )";
		const { run } = start( async function* ( ctx ) {
			await ctx.nextInput();
			permission = await ctx.ask( BROWSER, { action: 'javascript_exec', text: script, tabId: 1 } );
			yield resultWith( 'done' );
			await ctx.nextInput();
		} );

		await waitFor( () => run.status === 'waiting' );

		const gate = run.snapshot().gates[ 0 ] as Extract<Gate, { type: 'approval' }>;

		expect( gate ).toMatchObject( { toolName: BROWSER, confirmPhrase: null } );
		expect( gate.command ).toContain( "method: 'POST'" );
		expect( gate.reason ).toMatch( /logged-in browser/ );

		run.resolveGate( gate.id, { type: 'approval', allow: true } );
		await waitFor( () => permission !== null );

		expect( permission ).toMatchObject( { behavior: 'allow' } );
		run.stop();
	} );

	it( 'lets read-only browser scripts and other Chrome tools run without asking', async () => {
		const permissions: ( PermissionResult | null )[] = [];
		const { run } = start( async function* ( ctx ) {
			await ctx.nextInput();
			permissions.push( await ctx.ask( BROWSER, { action: 'javascript_exec', text: 'document.title', tabId: 1 } ) );
			permissions.push( await ctx.ask( 'mcp__claude-in-chrome__computer', { action: 'left_click', coordinate: [ 1, 2 ] } ) );
			yield resultWith( 'done' );
			await ctx.nextInput();
		} );

		await waitFor( () => run.status === 'awaiting_reply' );

		expect( permissions.map( ( item ) => item?.behavior ) ).toEqual( [ 'allow', 'allow' ] );
		run.stop();
	} );

	it( 'forces a browser write to ask even when the allowlist permits it', async () => {
		const input = {
			hook_event_name: 'PreToolUse',
			tool_name: BROWSER,
			tool_input: { text: "fetch('/x', { method: 'DELETE' })" },
			tool_use_id: 't',
			session_id: 's',
			transcript_path: '',
			cwd: '/repo',
		} as HookInput;

		expect( await forceAskHook( input ) ).toMatchObject( { hookSpecificOutput: { permissionDecision: 'ask' } } );
		expect( await forceAskHook( { ...input, tool_input: { text: 'document.title' } } as HookInput ) ).toEqual( {} );
	} );
} );

describe( 'command reports', () => {
	it( 'records the report from each turn, keeping the latest, and sends it in meta events', async () => {
		const { run } = start( async function* ( ctx ) {
			await ctx.nextInput();
			yield text( 'Checking.' );
			yield resultWith( report( 'blocked', 'The release PR has not merged.' ) );
			await ctx.nextInput();
			yield resultWith( report( 'ok', 'Tagged and published.' ) );
			await ctx.nextInput();
		} );
		const events: RunEvent[] = [];

		run.on( 'event', ( event: RunEvent ) => events.push( event ) );

		await waitFor( () => run.status === 'awaiting_reply' );
		expect( run.snapshot().outcome ).toMatchObject( { status: 'blocked', followups: [ 'Merge the PR' ] } );

		run.reply( 'It has merged now.' );
		// An ok report finishes the run by itself.
		await waitFor( () => run.status === 'done' && run.outcome?.status === 'ok' );

		expect( events.filter( ( event ) => event.type === 'meta' ).at( -1 ) ).toMatchObject( { outcome: { status: 'ok' } } );
	} );

	it( 'clears the report when a later turn writes none', async () => {
		const { run } = start( async function* ( ctx ) {
			await ctx.nextInput();
			yield resultWith( report( 'blocked', 'Waiting.' ) );
			await ctx.nextInput();
			yield resultWith( 'Just a reply, no report.' );
			await ctx.nextInput();
		} );

		await waitFor( () => run.outcome !== null );
		run.reply( 'ok' );
		await waitFor( () => run.status === 'awaiting_reply' && run.outcome === null );

		run.stop();
	} );

	it( 'saves the report with the run and lists it in the history', async () => {
		const store = new MemoryRunStore();
		const manager = new RunManager(
			'/repo',
			scriptedQuery( async function* ( ctx ) {
				await ctx.nextInput();
				yield resultWith( report( 'ok', 'Done.' ) );
				await ctx.nextInput();
			} ).queryFn,
			{},
			store
		);
		const run = manager.start( 'prep', '4.17.5', '/x' );

		await waitFor( () => run.status === 'done' );

		expect( store.saved.get( run.id )?.status ).toBe( 'done' );
		expect( store.saved.get( run.id )?.outcome?.status ).toBe( 'ok' );
		expect( manager.list()[ 0 ].outcome?.summary ).toBe( 'Done.' );
	} );
} );

describe( 'per-stage session options', () => {
	it( 'gives each stage its own SDK options', async () => {
		const scripted = scriptedQuery( async function* ( ctx ) {
			await ctx.nextInput();
			yield resultWith( 'ok' );
			await ctx.nextInput();
		} );
		const sneaky = async () => ( { behavior: 'allow' as const, updatedInput: {} } );
		const manager = new RunManager( '/repo', scripted.queryFn, ( stageId ) =>
			stageId === 'blog-draft'
				? { extraArgs: { chrome: null }, env: { LITE_REPO: '/lite' }, permissionMode: 'bypassPermissions', canUseTool: sneaky, hooks: {} }
				: { env: { LITE_REPO: '/lite' } }
		);

		const browser = manager.start( 'blog-draft', '4.17.5', '/x' );
		await waitFor( () => browser.status === 'awaiting_reply' );
		browser.finish();

		const plain = manager.start( 'prep', '4.17.5', '/x' );
		await waitFor( () => plain.status === 'awaiting_reply' );
		plain.finish();

		expect( scripted.calls[ 0 ].options ).toMatchObject( { extraArgs: { chrome: null }, env: { LITE_REPO: '/lite' } } );
		expect( scripted.calls[ 1 ].options.extraArgs ).toBeUndefined();
		expect( scripted.calls[ 1 ].options.env ).toEqual( { LITE_REPO: '/lite' } );
		// A stage's options can never replace the console's approvals, hooks or permission mode.
		expect( scripted.calls[ 0 ].options.permissionMode ).toBe( 'acceptEdits' );
		expect( scripted.calls[ 0 ].options.canUseTool ).not.toBe( sneaky );
		expect( scripted.calls[ 0 ].options.hooks?.PreToolUse ).toHaveLength( 1 );
	} );

	it( 'uses the stage’s options when resuming, too', async () => {
		const scripted = scriptedQuery( async function* ( ctx ) {
			await ctx.nextInput();
			yield resultWith( 'ok' );
			await ctx.nextInput();
		} );
		const manager = new RunManager( '/repo', scripted.queryFn, ( stageId ) => ( stageId === 'notifications' ? { extraArgs: { chrome: null } } : {} ) );
		const first = manager.start( 'notifications', '4.17.5', '/x' );

		await waitFor( () => first.status === 'awaiting_reply' );
		first.finish();

		const resumed = manager.resume( first.id, 'again' );
		await waitFor( () => resumed.status === 'awaiting_reply' );

		expect( scripted.calls[ 1 ].options ).toMatchObject( { extraArgs: { chrome: null }, resume: 'session-1' } );
		resumed.stop();
	} );
} );

